import { z } from "zod";

/**
 * 3D car manifest (`public/models/car.manifest.json`) — docs/3D-CONTRACT.md §F4.
 *
 * Generated by the Blender pipeline (`3d/blender/export.py` → `3d/scripts/optimize.mjs`) from the
 * scene; never edited by hand. Space is glTF / vehicle space in meters: +Y up, +Z front, +X left.
 * The runtime loader (step 10) parses it with `parseCarManifest` before touching the GLB.
 */

const vec3 = z.tuple([z.number(), z.number(), z.number()]);
const box3 = z.object({ min: vec3, max: vec3 });
const cam = z.object({ position: vec3, target: vec3, fov: z.number().positive() });
const window01 = z.tuple([z.number().min(0).max(1), z.number().min(0).max(1)]);

const modelFile = z.object({
  url: z.string().startsWith("/models/"),
  bytes: z.number().int().positive(),
  sha256: z.string().regex(/^[0-9a-f]{64}$/),
  triangles: z.number().int().positive(),
  drawCalls: z.number().int().positive(),
  textures: z.number().int().nonnegative(),
});

const partNode = z.string().regex(/^part__[a-z0-9-]+__[a-z0-9-]+$/);

export const carManifestSchema = z.object({
  schemaVersion: z.literal(1),
  generatedAt: z.string(),
  source: z.object({ blender: z.string(), scriptsHash: z.string().regex(/^[0-9a-f]{64}$/) }),
  models: z.object({ desktop: modelFile, lite: modelFile }),
  units: z.literal("meters"),
  axes: z.object({ up: z.literal("+Y"), front: z.literal("+Z"), left: z.literal("+X") }),
  bbox: box3,
  systems: z.array(
    z.object({ slug: z.string(), labelSr: z.string().min(1), order: z.number().int() }),
  ),
  stages: z.array(
    z.object({
      stage: z.number().int().min(0).max(7),
      key: z.string(),
      labelSr: z.string().min(1),
      scroll: z.object({ desktop: window01, mobile: window01 }),
    }),
  ),
  categories: z.array(
    z.object({
      slug: z.string(),
      labelSr: z.string().min(1),
      system: z.string(),
      nodes: z.array(partNode),
      hasMesh: z.boolean(),
      thumbnail: z.string().regex(/^\/images\/parts\/[a-z0-9-]+\.webp$/),
      focus: z.object({
        dir: vec3,
        minDistance: z.number().nonnegative(),
        fov: z.number().positive(),
      }),
    }),
  ),
  parts: z.array(
    z.object({
      node: partNode,
      partId: z.string(),
      category: z.string(),
      system: z.string(),
      labelSr: z.string().min(1),
      clickable: z.boolean(),
      lod: z.enum(["core", "detail"]),
      explode: z.object({
        dir: vec3,
        distance: z.number().nonnegative(),
        stage: z.number().int().min(1).max(7),
        order: z.number().min(0).max(1),
      }),
      pivot: vec3,
      bbox: box3,
      labelAnchor: vec3,
      triangles: z.object({
        desktop: z.number().int().nonnegative(),
        lite: z.number().int().nonnegative(),
      }),
      materials: z.array(z.string().startsWith("mat_")),
    }),
  ),
  cameras: z.object({
    hero: z.object({ desktop: cam, mobile: cam }),
    exploded: z.object({ desktop: cam, mobile: cam }),
  }),
  materials: z.array(
    z.object({
      name: z.string().startsWith("mat_"),
      override: z.enum(["xray-body", "xray-glass"]).optional(),
    }),
  ),
});

export type CarManifest = z.infer<typeof carManifestSchema>;
export type ManifestPart = CarManifest["parts"][number];
export type ManifestCategory = CarManifest["categories"][number];
export type ManifestCamera = CarManifest["cameras"]["hero"]["desktop"];
export type Vec3 = [number, number, number];

/** Validates unknown JSON (fetched at runtime or read in tests) against the contract. */
export function parseCarManifest(json: unknown): CarManifest {
  return carManifestSchema.parse(json);
}

/**
 * Explode offset of a part at scroll progress `p` for the given stage window
 * (PLAN §6.2 / contract F6): `u` is the progress inside the window, `order` staggers the part
 * inside its stage by up to 35 % of the window, easing is power2.inOut.
 */
export function explodeFactor(p: number, window: readonly [number, number], order: number): number {
  const [start, end] = window;
  const u = Math.min(Math.max((p - start) / (end - start), 0), 1);
  const local = Math.min(Math.max((u - 0.35 * order) / 0.65, 0), 1);
  return local < 0.5 ? 2 * local * local : 1 - (-2 * local + 2) ** 2 / 2;
}
